{"command":"cat <<'EOF' > gen.py
import os
import glob

print('package main')
print('import ("fmt"; "os"; "strings"; "flag")')

# Typos and distances
print('''
func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
func levenshtein(a, b string) int {
	if len(a) == 0 {
		return len(b)
	}
	if len(b) == 0 {
		return len(a)
	}
	matrix := make([][]int, len(a)+1)
	for i := range matrix {
		matrix[i] = make([]int, len(b)+1)
		matrix[i][0] = i
	}
	for j := range matrix[0] {
		matrix[0][j] = j
	}
	for i := 1; i <= len(a); i++ {
		for j := 1; j <= len(b); j++ {
			cost := 1
			if a[i-1] == b[j-1] {
				cost = 0
			}
			min := matrix[i-1][j] + 1
			if matrix[i][j-1]+1 < min {
				min = matrix[i][j-1] + 1
			}
			if matrix[i-1][j-1]+cost < min {
				min = matrix[i-1][j-1] + cost
			}
			matrix[i][j] = min
		}
	}
	return matrix[len(a)][len(b)]
}
''')

docs = {}
for f in glob.glob('extract/*.txt'):
    name = os.path.basename(f)[:-4]
    if name in ['doc', 'help', 'version', 'empty', 'check_help']: continue
    with open(f, 'r') as file:
        docs[name] = file.read()

print('var docs = map[string]string{')
for k, v in docs.items():
    print(f'"{k}": `{v}`,')
print('}')

with open('extract/doc.txt', 'r') as f:
    doc_txt = f.read()

with open('extract/help.txt', 'r') as f:
    help_txt = f.read()

with open('extract/version.txt', 'r') as f:
    version_txt = f.read()

with open('extract/check_help.txt', 'r') as f:
    check_help_txt = f.read()

print(f'var docTxt = `{doc_txt}`')
print(f'var helpTxt = `{help_txt}`')
print(f'var versionTxt = `{version_txt}`')
print(f'var checkHelpTxt = `{check_help_txt}`')

print('''
func suggestCommand(cmd string) string {
	commands := []string{"check", "doc", "help", "version"}
	minDist := -1
	bestMatch := ""
	for _, c := range commands {
		dist := levenshtein(cmd, c)
		if minDist == -1 || dist < minDist {
			minDist = dist
			bestMatch = c
		}
	}
	if minDist <= 3 {
		return bestMatch
	}
	return "help"
}

func printUnknown(cmd string) {
    if cmd == "-h" {
        fmt.Fprintf(os.Stdout, `"%s" unknown command
Run "go-critic help" for usage.

`, cmd)
        fmt.Fprintf(os.Stderr, "no such command \"%s\"\n", cmd)
        return
    }
	suggestion := suggestCommand(cmd)
	if suggestion != "help" {
		fmt.Fprintf(os.Stdout, `"%s" unknown command, did you mean "%s"?
Run "go-critic help" for usage.

`, cmd, suggestion)
	} else {
		fmt.Fprintf(os.Stdout, `"%s" unknown command
Run "go-critic help" for usage.

`, cmd)
	}
	fmt.Fprintf(os.Stderr, "no such command \"%s\"\n", cmd)
}

func main() {
	if len(os.Args) == 1 {
		fmt.Println("no args provided")
		os.Exit(0)
	}

	cmd := os.Args[1]
	switch cmd {
	case "help":
		fmt.Print(helpTxt)
	case "version":
		fmt.Print(versionTxt)
	case "doc":
		if len(os.Args) == 2 {
			fmt.Print(docTxt)
		} else {
			checker := os.Args[2]
			if doc, ok := docs[checker]; ok {
				fmt.Print(doc)
			} else {
				fmt.Printf("checker with name \\"%s\\" not found\\n", checker)
				os.Exit(1)
			}
		}
	case "check":
		if len(os.Args) > 2 && os.Args[2] == "-help" {
			fmt.Print(checkHelpTxt)
            os.Exit(1)
		}
        // TODO: implement some checkers here if needed!
	default:
		printUnknown(cmd)
	}
}
''')
EOF
python3 gen.py > main.go
go build -o my_exec main.go
"}

